def fix_spaces(text):
    result = []
    consecutive = 0

    for char in text:
        if char == ' ':
            consecutive += 1
        else:
            if consecutive > 2:
                result.append('-')
            elif consecutive > 1:
                result.extend(['_', '_'])
            elif consecutive == 1:
                result.append('_')
            consecutive = 0
            result.append(char)

    if consecutive > 2:
        result.append('-')
    elif consecutive > 1:
        result.extend(['_', '_'])
    elif consecutive == 1:
        result.append('_')

    return ''.join(result)

def specialFilter(nums):
    def is_odd(n):
        return n % 2 != 0

    def first_last_odd(n):
        return is_odd(n % 10) and is_odd(int(str(n)[0]))

    return sum(1 for n in nums if n > 10 and first_last_odd(n))

